_runBundledClassicScript("/static/js/features/shortcuts/shortcuts_key_handler.js", "// Global shortcuts-overlay keyboard handler.\n//\n// Opens the shortcuts overlay with \"?\" when the current text field is empty,\n// while letting literal question marks type normally inside non-empty inputs.\ndocument.addEventListener('keydown', e => {\n  if (e.key !== '?') return;\n  if (e.ctrlKey || e.metaKey || e.altKey) return;\n  const ae = document.activeElement;\n  if (ae) {\n    const tag = (ae.tagName || '').toLowerCase();\n    const isEditable = ae.isContentEditable;\n    const isTextInput =\n      tag === 'textarea' ||\n      (tag === 'input' && !/^(checkbox|radio|button|submit|reset|range|color|file)$/i.test(ae.type || '')) ||\n      isEditable;\n    if (tag === 'select') return;\n    if (isTextInput) {\n      if (\n        (ae === cmdInput || ae === mobileCmdInput)\n        && typeof syncFocusedComposerState === 'function'\n      ) {\n        syncFocusedComposerState(ae);\n      }\n      const raw = isEditable ? (ae.textContent || '') : (ae.value || '');\n      if (raw.length > 0) return;\n    }\n  }\n  e.preventDefault();\n  e.stopImmediatePropagation();\n  if (\n    typeof _welcomeActive !== 'undefined' && _welcomeActive\n    && typeof activeTabId !== 'undefined'\n    && typeof welcomeOwnsTab === 'function'\n    && welcomeOwnsTab(activeTabId)\n    && typeof requestWelcomeSettle === 'function'\n  ) {\n    requestWelcomeSettle(activeTabId);\n  }\n  if (typeof isShortcutsOverlayOpen === 'function' && isShortcutsOverlayOpen()) {\n    closeShortcuts();\n  } else {\n    openShortcuts();\n  }\n}, true);\n\n//# sourceURL=/static/js/features/shortcuts/shortcuts_key_handler.js");
